//! Export the DTOs that cross the shell boundary to TypeScript.
//!
//! Run with:
//!
//! ```bash
//! cargo run -p phi-node --bin export-types
//! ```
//!
//! The generated files live in `src/generated/` and are checked in. The
//! frontend never hand-mirrors these shapes; `src/types.ts` and
//! `src/settings/types.ts` re-export them. Large integers are exported as
//! `number` to match how `serde_json` renders them for the webview.

use std::error::Error;
use std::fs;
use std::path::{Path, PathBuf};

use ts_rs::{Config, TS};

use phi_contracts::auxiliary::ImageAsset;
use phi_contracts::memory::{ForgetReport, MemoryAddOutcome, MemoryHit, MemoryStats};
use phi_contracts::ports::{ModelStatus, ThinkingEffort};
use phi_contracts::provider::{ModelSpec, Protocol, ProviderInput, ProviderTestView, ProviderView};
use phi_contracts::stream::ModelStreamEvent;
use phi_domain::memory::MemoryRecord;
use phi_domain::message::{ContentBlock, Role};
use phi_domain::view::{PendingApprovalView, SessionSummary, SessionView};
use phi_node::{Bootstrap, SendResult, SessionDetail};

fn main() -> Result<(), Box<dyn Error>> {
    let manifest = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let repo_root = manifest
        .ancestors()
        .nth(3)
        .ok_or("could not locate the repository root")?;
    let out_dir = repo_root.join("src").join("generated");

    if out_dir.exists() {
        fs::remove_dir_all(&out_dir)?;
    }
    fs::create_dir_all(&out_dir)?;

    let config = Config::new()
        .with_large_int("number")
        .with_out_dir(&out_dir);

    // Each root pulls in the types it references, so this list only needs one
    // entry per reachable DTO cluster.
    Bootstrap::export_all(&config)?;
    SessionDetail::export_all(&config)?;
    SendResult::export_all(&config)?;
    ModelStatus::export_all(&config)?;
    ModelStreamEvent::export_all(&config)?;
    ImageAsset::export_all(&config)?;
    ThinkingEffort::export_all(&config)?;
    ModelSpec::export_all(&config)?;
    ProviderView::export_all(&config)?;
    ProviderInput::export_all(&config)?;
    ProviderTestView::export_all(&config)?;
    Protocol::export_all(&config)?;
    SessionSummary::export_all(&config)?;
    SessionView::export_all(&config)?;
    PendingApprovalView::export_all(&config)?;
    ContentBlock::export_all(&config)?;
    Role::export_all(&config)?;
    MemoryRecord::export_all(&config)?;
    MemoryStats::export_all(&config)?;
    MemoryHit::export_all(&config)?;
    MemoryAddOutcome::export_all(&config)?;
    ForgetReport::export_all(&config)?;

    write_index(&out_dir)?;

    println!("exported TypeScript DTOs to {}", out_dir.display());
    Ok(())
}

/// Write a barrel file so the frontend can import every DTO from one path.
fn write_index(out_dir: &Path) -> Result<(), Box<dyn Error>> {
    let mut files = Vec::new();
    collect_ts_files(out_dir, out_dir, &mut files)?;
    files.sort();

    let mut source = String::from(
        "// This file is generated by `cargo run -p phi-node --bin export-types`.\n\
         // Do not edit it manually.\n\n",
    );
    for relative in files {
        let stem = relative
            .file_stem()
            .and_then(|name| name.to_str())
            .ok_or("generated file has no name")?;
        let path = relative
            .with_extension("")
            .to_string_lossy()
            .replace('\\', "/");
        source.push_str(&format!("export type {{ {stem} }} from \"./{path}\";\n"));
    }

    fs::write(out_dir.join("index.ts"), source)?;
    Ok(())
}

fn collect_ts_files(
    root: &Path,
    dir: &Path,
    files: &mut Vec<PathBuf>,
) -> Result<(), Box<dyn Error>> {
    for entry in fs::read_dir(dir)? {
        let entry = entry?;
        let path = entry.path();
        if path.is_dir() {
            collect_ts_files(root, &path, files)?;
        } else if path.extension().is_some_and(|ext| ext == "ts")
            && path.file_name().is_some_and(|name| name != "index.ts")
        {
            files.push(path.strip_prefix(root)?.to_path_buf());
        }
    }
    Ok(())
}
